/* @component: mod-popup */
(function () {
  const css = `
    .btn-open:hover {
      border: 1px solid var(--navy-900);
      background-color: var(--navy-900);
    }

    .btn-open:active {
      transform: translateY(1px);
    }

    .mod-popup::backdrop {
      background-color: rgba(0, 0, 0, 0.95);
      backdrop-filter: blur(4px);
    }

    .mod__close:hover {
      color: var(--accent);
    }
  `;

  const style = document.createElement('style');
  style.textContent = css;
  document.head.appendChild(style);

  document.addEventListener('click', function (event) {
    const closeButton = event.target.closest('.mod__close');
    if (closeButton) {
      const modal = closeButton.closest('dialog') || document.querySelector('.mod-popup');
      if (modal && typeof modal.close === 'function') {
        modal.close();
      }
      return;
    }

    const openButton = event.target.closest('.btn-open');
    if (!openButton) {
      return;
    }

    const targetId = openButton.getAttribute('data-target');
    const modal = targetId ? document.getElementById(targetId) : document.querySelector('.mod-popup');

    if (modal && typeof modal.showModal === 'function') {
      modal.showModal();
    }
  });

  document.querySelectorAll('.mod-popup').forEach(function (modal) {
    modal.addEventListener('click', function (event) {
      if (event.target === modal) {
        modal.close();
      }
    });
  });
})();/* @component: mod-popup */
